	host.set_parameters({"level": int(settings.level)})
	if int(settings.level) < 3:
		var allowed := ["Foundation", "TargetA"]
		if int(settings.level) == 2:
			allowed.append_array(["TargetB", "Cover"])
		for child in host.get_node("World").get_children():
			if child is Node3D:
