{"path":"effect/interaction_field.gd","content":"extends RefCounted
## World-aligned cell-centred RGBA float field. No frame history approximation.
var origin := Vector2.ZERO
var size_m := 8.0
var width := 64
var height := 64
var values := PackedFloat32Array()
var elapsed := 0.0
var frame := 0
var player_position := Vector2.ZERO
var player_velocity := Vector2.ZERO
var active := true
var config: Dictionary
var image: Image
var texture: ImageTexture

func configure(inputs: Dictionary) -> void:
	config = inputs
	origin = Vector2(inputs.patch.origin_xz_m[0], inputs.patch.origin_xz_m[1])
	size_m = float(inputs.patch.size_m)
	width = int(inputs.patch.resolution[0])
	height = int(inputs.patch.resolution[1])
	values.resize(width * height * 4)
	values.fill(0.0)
	elapsed = 0.0
	frame = 0
	update_player()
	image = Image.create_from_data(width, height, false, Image.FORMAT_RGBAF, values.to_byte_array())
	texture = ImageTexture.create_from_image(image)

func update_player() -> void:
	var keys: Array = config.player_keyframes
	var last: Array = keys[-1].position_xz_m
	player_position = Vector2(last[0], last[1])
	player_velocity = Vector2.ZERO
	for i in range(keys.size() - 1):
		var a: Dictionary = keys[i]
		var b: Dictionary = keys[i + 1]
		if elapsed < float(b.time_s):
			var p0 := Vector2(a.position_xz_m[0], a.position_xz_m[1])
			var p1 := Vector2(b.position_xz_m[0], b.position_xz_m[1])
			var duration := float(b.time_s) - float(a.time_s)
			player_velocity = (p1 - p0) / duration
			player_position = p0.lerp(p1, clampf((elapsed - float(a.time_s)) / duration, 0.0, 1.0))
			break
	# Treat the removal boundary as exclusive, including accumulated FP roundoff.
	active = elapsed < float(config.interaction_active_until_s) - 1.0e-9

func step(dt: float) -> void:
	frame += 1
	elapsed += dt
	update_player()
	var decay := pow(float(config.interaction.persistence_per_60hz_step), dt * 60.0)
	var radius := float(config.interaction.radius_m)
	var strength := float(config.interaction.strength)
	for y in range(height):
		for x in range(width):
			var index := (y * width + x) * 4
			for c in range(3):
				values[index + c] *= decay
			if not active:
				continue
			var point := origin + Vector2((float(x) + 0.5) / width, (float(y) + 0.5) / height) * size_m
			var offset := point - player_position
			var distance := offset.length()
			if distance >= radius:
				continue
			var influence := strength * pow(1.0 - distance / radius, 2.0)
			if influence > values[index + 2]:
				var direction := offset / distance if distance > 1.0e-8 else player_velocity.normalized()
				values[index] = direction.x * influence
				values[index + 1] = direction.y * influence
				values[index + 2] = influence
	image.set_data(width, height, false, Image.FORMAT_RGBAF, values.to_byte_array())
	texture.update(image)

func cell(x: int, y: int) -> Vector3:
	if x < 0 or x >= width or y < 0 or y >= height:
		return Vector3.ZERO
	var index := (y * width + x) * 4
	return Vector3(values[index], values[index + 1], values[index + 2])

func sample_at(point: Vector2) -> Vector3:
	var uv := (point - origin) / size_m
	if uv.x < 0.0 or uv.x >= 1.0 or uv.y < 0.0 or uv.y >= 1.0:
		return Vector3.ZERO
	var grid := uv * Vector2(width, height) - Vector2(0.5, 0.5)
	var x := int(floor(grid.x))
	var y := int(floor(grid.y))
	var f := grid - Vector2(x, y)
	return cell(x, y).lerp(cell(x + 1, y), f.x).lerp(cell(x, y + 1).lerp(cell(x + 1, y + 1), f.x), f.y)

func as_rows() -> Array:
	var result: Array = []
	for i in range(width * height):
		result.append([values[i * 4], values[i * 4 + 1], values[i * 4 + 2], 0.0])
	return result
"}

{"path":"effect/grass.gdshader","content":"shader_type spatial;
render_mode cull_disabled, diffuse_burley, specular_schlick_ggx, world_vertex_coords;

uniform sampler2D grass_albedo : source_color, filter_linear_mipmap, repeat_disable;
uniform sampler2D grass_orm : filter_linear_mipmap, repeat_disable;
// Host-compatible inputs; wind and raw player history deliberately do not drive vertices.
uniform float elapsed = 0.0;
uniform float wind_strength = 0.0;
uniform float wind_speed = 1.6;
uniform vec2 wind_direction = vec2(1.0, 0.35);
uniform vec3 player_position = vec3(-4.0, 0.0, 0.0);
uniform float interaction_radius = 0.95;
uniform float interaction_strength = 0.95;
uniform vec4 player_history[32];
uniform bool audit_roots = false;
uniform bool audit_tips = false;
uniform sampler2D interaction_field : filter_nearest, repeat_disable;
uniform vec2 patch_origin = vec2(-4.0);
uniform float patch_size = 8.0;
uniform float bend_m = 0.35;
uniform float flatten_m = 0.1;
uniform vec3 bottom_left;
uniform vec3 bottom_right;
uniform vec3 top_left;
uniform vec3 top_right;

vec3 cell(ivec2 p) {
	ivec2 size = textureSize(interaction_field, 0);
	if (p.x < 0 || p.y < 0 || p.x >= size.x || p.y >= size.y) { return vec3(0.0); }
	return texelFetch(interaction_field, p, 0).rgb;
}
vec3 field_at(vec2 point) {
	vec2 uv = (point - patch_origin) / patch_size;
	if (any(lessThan(uv, vec2(0.0))) || any(greaterThanEqual(uv, vec2(1.0)))) { return vec3(0.0); }
	vec2 grid = uv * vec2(textureSize(interaction_field, 0)) - vec2(0.5);
	ivec2 p = ivec2(floor(grid));
	vec2 f = fract(grid);
	return mix(mix(cell(p), cell(p + ivec2(1, 0)), f.x),
		mix(cell(p + ivec2(0, 1)), cell(p + ivec2(1, 1)), f.x), f.y);
}
void vertex() {
	vec3 field = field_at(MODEL_MATRIX[3].xz);
	float h = clamp(UV2.y, 0.0, 1.0);
	float s = UV2.x;
	vec3 displacement = vec3(field.x * bend_m, -field.z * flatten_m, field.y * bend_m);
	// Uniform bend for each rooted card, zero position and slope change at its base.
	VERTEX += displacement * h * h;
	vec3 ds = mat3(MODEL_MATRIX) * mix(bottom_right - bottom_left, top_right - top_left, h);
	vec3 dh = mat3(MODEL_MATRIX) * mix(top_left - bottom_left, top_right - bottom_right, s);
	dh += displacement * (2.0 * h);
	vec3 n = normalize(cross(ds, dh));
	NORMAL = dot(n, NORMAL) < 0.0 ? -n : n;
}
void fragment() {
	vec4 base = texture(grass_albedo, UV);
	vec3 orm = texture(grass_orm, UV).rgb;
	ALBEDO = base.rgb;
	ROUGHNESS = clamp(orm.g, 0.55, 1.0);
	METALLIC = 0.0;
	AO = mix(0.75, 1.0, orm.r);
	BACKLIGHT = base.rgb * 0.18;
	NORMAL = FRONT_FACING ? NORMAL : -NORMAL;
	ALPHA = base.a;
	ALPHA_SCISSOR_THRESHOLD = 0.45;
	if (audit_roots || audit_tips) {
		bool keep = (audit_roots && UV2.y < 0.01) || (audit_tips && UV2.y > 0.99);
		ALPHA = keep ? 1.0 : 0.0;
		ALBEDO = vec3(0.0);
		EMISSION = audit_roots ? vec3(1.0,0.0,0.5) : vec3(0.0,0.5,1.0);
	}
}
"}

{"path":"effect/grass_geometry.gd","content":"extends RefCounted
## Read-only geometry cache in host node / instance / surface vertex order.
var cards: Array = []
var bend_m := 0.35
var flatten_m := 0.1

func configure(root: Node, inputs: Dictionary, field) -> void:
	cards.clear()
	bend_m = float(inputs.interaction.bend_m)
	flatten_m = float(inputs.interaction.flatten_m)
	for node in root.grass_nodes:
		var mm: MultiMesh = node.multimesh
		var arrays: Array = mm.mesh.surface_get_arrays(0)
		var vertices: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]
		var uv2: PackedVector2Array = arrays[Mesh.ARRAY_TEX_UV2]
		var normals: PackedVector3Array = arrays[Mesh.ARRAY_NORMAL]
		# Recover parametric card corners from actual geometry, never from asset constants.
		var corners: Array[Vector3] = [Vector3.ZERO, Vector3.ZERO, Vector3.ZERO, Vector3.ZERO]
		for v in range(vertices.size()):
			if uv2[v].is_equal_approx(Vector2(0, 0)): corners[0] = vertices[v]
			if uv2[v].is_equal_approx(Vector2(1, 0)): corners[1] = vertices[v]
			if uv2[v].is_equal_approx(Vector2(0, 1)): corners[2] = vertices[v]
			if uv2[v].is_equal_approx(Vector2(1, 1)): corners[3] = vertices[v]
		var mat: ShaderMaterial = root.material.duplicate()
		mat.set_shader_parameter("interaction_field", field.texture)
		mat.set_shader_parameter("patch_origin", field.origin)
		mat.set_shader_parameter("patch_size", field.size_m)
		mat.set_shader_parameter("bend_m", bend_m)
		mat.set_shader_parameter("flatten_m", flatten_m)
		mat.set_shader_parameter("bottom_left", corners[0])
		mat.set_shader_parameter("bottom_right", corners[1])
		mat.set_shader_parameter("top_left", corners[2])
		mat.set_shader_parameter("top_right", corners[3])
		mat.set_shader_parameter("wind_strength", 0.0)
		node.material_override = mat
		for i in range(mm.instance_count):
			var transform: Transform3D = node.global_transform * mm.get_instance_transform(i)
			cards.append({"transform": transform, "vertices": vertices, "uv2": uv2, "normals": normals, "corners": corners})

func evaluate(field) -> Dictionary:
	var positions: Array = []
	var normals: Array = []
	var root_error := 0.0
	var normal_error := 0.0
	var max_shift := 0.0
	for card in cards:
		var transform: Transform3D = card.transform
		var origin: Vector3 = transform.origin
		var value: Vector3 = field.sample_at(Vector2(origin.x, origin.z))
		var delta := Vector3(value.x * bend_m, -value.z * flatten_m, value.y * bend_m)
		var corners: Array = card.corners
		var normal_basis := transform.basis.inverse().transposed()
		for i in range(card.vertices.size()):
			var h := clampf(card.uv2[i].y, 0.0, 1.0)
			var s: float = card.uv2[i].x
			var original: Vector3 = transform * card.vertices[i]
			var point := original + delta * h * h
			var ds: Vector3 = transform.basis * (corners[1] - corners[0]).lerp(corners[3] - corners[2], h)
			var dh: Vector3 = transform.basis * (corners[2] - corners[0]).lerp(corners[3] - corners[1], s) + delta * (2.0 * h)
			var normal := ds.cross(dh).normalized()
			if normal.dot(normal_basis * card.normals[i]) < 0.0:
				normal = -normal
			positions.append([point.x, point.y, point.z])
			normals.append([normal.x, normal.y, normal.z])
			if h == 0.0: root_error = maxf(root_error, point.distance_to(original))
			normal_error = maxf(normal_error, absf(normal.length() - 1.0))
			max_shift = maxf(max_shift, point.distance_to(original))
	print("GEOMETRY_CHECK frame=", field.frame, " instances=", cards.size(), " vertices=", positions.size(), " root_error=", root_error, " unit_normal_error=", normal_error, " max_shift_m=", max_shift)
	return {"positions": positions, "normals": normals}
"}

